# Create new column 'PhoenixPoints' = 'Score' sub Score
print(f"🔧 Creating column 'PhoenixPoints' = 'Score' sub Score")

# Check if operation is valid
if "sub" not in ['add', 'sub', 'mul', 'div', 'ratio']:
    print(f"❌ Error: Invalid operation 'sub'. Valid operations: ['add', 'sub', 'mul', 'div', 'ratio']")
elif 'Score' not in df.columns:
    print(f"❌ Error: Column 'Score' not found")
    print(f"Available columns: {df.columns.tolist()}")
else:
    try:
        # Check if col_B is a column name or scalar
        if isinstance(Score, str) and Score not in df.columns:
            print(f"❌ Error: Column 'Score' not found")
            print(f"Available columns: {df.columns.tolist()}")
        else:
            # Perform the operation
            if "sub" == "add":
                df['PhoenixPoints'] = df['Score'] + Score
            elif "sub" == "sub":
                df['PhoenixPoints'] = df['Score'] - Score
            elif "sub" == "mul":
                df['PhoenixPoints'] = df['Score'] * Score
            elif "sub" in ["div", "ratio"]:
                df['PhoenixPoints'] = df['Score'] / Score

            print(f"✅ Successfully created column 'PhoenixPoints'")
            print(f"📊 New table shape: {df.shape}")
            print(f"🔍 New column preview:")
            print(df[['Score', 'PhoenixPoints']].head())

    except Exception as e:
        print(f"❌ Error creating column: {e}")
        print(f"Check data types and values for division by zero")
